/* Headline Intelligence — scoring + UI
 *
 * No dependencies, no build step, no network calls. Everything runs locally.
 *
 * `assets/data.js` (generated by pipeline/build_data.py) defines window.HI with
 * the fitted model, the mined per-platform rules and the lexicons. The feature
 * extractor below is a line-for-line port of pipeline/features.py — the two are
 * checked against each other by pipeline/verify.py, which fails CI if they drift.
 */
(() => {
  'use strict';

  const { LEX, MODEL, RULES, COND, TEMPLATES, SUBSHAPES, TAGS, PLAT_NAME, META } = window.HI;

  // ------------------------------------------------------------------ regex
  const RE = {
    list: /^\s*(\d{1,3})\s+\S/,
    num: /\d/,
    year: /\b(19|20)\d{2}\b/,
    colon: /:/,
    question: /\?/,
    paren: /[([]/,
    quote: /["“”‘’'«»]/,
    // an apostrophe inside a word (don't, writers') is not a quotation mark
    apos: /([A-Za-z0-9])['’](?=[A-Za-z0-9]|\s|$)/g,
    cmp: /\b(vs\.?|versus|better than|instead of|compared to|or)\b/i,
    howto: /^\s*(how to|how i|how we|how )/i,
    why: /^\s*why\b/i,
    wh: /^\s*(what|which|when|where|who)\b/i,
    imperative: /^\s*(stop|start|use|build|write|read|learn|avoid|do|don't|never|always|make|get|forget|try)\b/i,
    superlative: /\b(best|worst|fastest|slowest|biggest|smallest|most|least|only|first|last|ultimate|definitive|complete)\b/i,
    you: /\b(you|your|you're|yours)\b/i,
    me: /\b(i|my|me|mine|we|our|us)\b/i,
    bigNum: /\b\d{2,}(?:[.,]\d+)?\s*(?:%|x|k|m|b|ms|s|gb|mb|tb|kb|hours?|days?|weeks?|months?|years?|lines?|times?)\b/i,
    money: /[$€£]\s?\d/,
    acronym: /\b[A-Z]{2,6}\b/g,
    dash: /[—–]/
  };

  const lexCache = {};
  function lexRe(key) {
    if (!lexCache[key]) {
      const terms = [...LEX[key]].sort((a, b) => b.length - a.length)
        .map(s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
      lexCache[key] = new RegExp('(?<![a-z0-9])(?:' + terms.join('|') + ')(?![a-z0-9])', 'g');
    }
    return lexCache[key];
  }
  const countLex = (low, key) => {
    const m = low.match(lexRe(key));
    return m ? new Set(m).size : 0;
  };

  const words = t => (t.toLowerCase().match(/[a-z0-9'\-]+/g) || []);

  function syllables(w) {
    w = w.toLowerCase().replace(/^['\-]+|['\-]+$/g, '');
    if (!w) return 0;
    let n = (w.match(/[aeiouy]+/g) || []).length;
    if (w.endsWith('e') && n > 1 && !/(le|ee|ye)$/.test(w)) n--;
    return Math.max(1, n);
  }

  function flesch(t) {
    const w = words(t);
    if (!w.length) return 0;
    const sentences = Math.max(1, (t.match(/[.!?]+/g) || []).length || 1);
    const syl = w.reduce((a, x) => a + syllables(x), 0);
    return 206.835 - 1.015 * (w.length / sentences) - 84.6 * (syl / w.length);
  }

  // -------------------------------------------------------------- features
  function titleFeatures(title) {
    const t = (title || '').trim();
    const low = t.toLowerCase();
    const w = words(t);
    const nw = w.length || 1;
    const cp = [...t].length;                       // code points, so emoji match Python
    const content = w.filter(x => !LEX.STOP.includes(x));
    const caps = t.split(/\s+/).filter(x => x && x[0] === x[0].toUpperCase() && /[A-Za-z]/.test(x[0]));
    const f = {};

    f.char_count = cp;
    f.word_count = w.length;
    f.avg_word_len = w.reduce((a, x) => a + x.length, 0) / nw;
    f.long_word_ratio = w.filter(x => x.length >= 8).length / nw;
    f.has_colon = RE.colon.test(t) ? 1 : 0;
    f.has_question = RE.question.test(t) ? 1 : 0;
    f.has_parens = RE.paren.test(t) ? 1 : 0;
    f.has_quotes = RE.quote.test(t.replace(RE.apos, '$1')) ? 1 : 0;
    f.has_dash = (RE.dash.test(t) || t.includes(' - ')) ? 1 : 0;
    f.title_case_ratio = caps.length / Math.max(1, t.split(/\s+/).filter(Boolean).length);
    f.all_caps_words = t.split(/\s+/).filter(x => x.length > 2 && x === x.toUpperCase() && /[A-Z]/.test(x)).length;

    f.has_number = RE.num.test(t) ? 1 : 0;
    const lm = t.match(RE.list);
    f.starts_with_number = lm ? 1 : 0;
    f.listicle_size = lm ? parseInt(lm[1], 10) : 0;
    f.has_year = RE.year.test(t) ? 1 : 0;
    f.has_big_number = RE.bigNum.test(t) ? 1 : 0;
    f.has_money = RE.money.test(t) ? 1 : 0;
    f.acronym_count = (t.match(RE.acronym) || []).length;
    f.digit_ratio = (t.match(/\d/g) || []).length / Math.max(1, cp);
    f.specificity = Math.min(1, (f.has_big_number + f.has_year + f.has_money
      + Math.min(2, f.acronym_count) * 0.5 + f.starts_with_number) / 3);

    f.is_howto = RE.howto.test(t) ? 1 : 0;
    f.is_why = RE.why.test(t) ? 1 : 0;
    f.is_wh_question = RE.wh.test(t) ? 1 : 0;
    f.is_imperative = RE.imperative.test(t) ? 1 : 0;
    f.is_listicle = f.starts_with_number;
    f.has_comparison = RE.cmp.test(t) ? 1 : 0;
    f.has_superlative = RE.superlative.test(t) ? 1 : 0;
    f.second_person = RE.you.test(t) ? 1 : 0;
    f.first_person = RE.me.test(t) ? 1 : 0;

    f.power_words = countLex(low, 'POWER');
    f.curiosity_markers = countLex(low, 'CURIOSITY');
    f.authority_markers = countLex(low, 'AUTHORITY');
    f.urgency_markers = countLex(low, 'URGENCY');
    f.negative_words = countLex(low, 'NEGATIVE');
    f.positive_words = countLex(low, 'POSITIVE');
    f.trust_words = countLex(low, 'TRUST');
    f.fear_words = countLex(low, 'FEAR');
    f.surprise_words = countLex(low, 'SURPRISE');
    f.excitement_words = countLex(low, 'EXCITEMENT');
    f.beginner_markers = countLex(low, 'BEGINNER');
    f.tech_depth_markers = countLex(low, 'TECHDEPTH');
    f.story_markers = countLex(low, 'STORY');
    f.ai_tells = countLex(low, 'AITELLS');

    f.curiosity_gap = Math.min(1, f.curiosity_markers * 0.45 + f.is_why * 0.3
      + f.has_question * 0.25 + f.surprise_words * 0.35);
    f.emotional_intensity = Math.min(1, f.power_words * 0.28 + f.fear_words * 0.3
      + f.excitement_words * 0.22 + f.surprise_words * 0.25);
    f.authority = Math.min(1, f.authority_markers * 0.3 + f.trust_words * 0.35
      + f.has_big_number * 0.25);
    f.promise_of_value = Math.min(1, f.is_howto * 0.4 + f.is_listicle * 0.35
      + f.beginner_markers * 0.2 + f.has_superlative * 0.15 + f.second_person * 0.15);
    f.novelty = Math.min(1, f.urgency_markers * 0.3 + f.excitement_words * 0.3
      + f.surprise_words * 0.3 + f.has_year * 0.2);
    f.sentiment = (f.positive_words - f.negative_words) / Math.max(1, content.length);
    f.negativity = f.negative_words / Math.max(1, content.length);

    f.readability = flesch(t);
    f.readability_norm = Math.max(0, Math.min(1, f.readability / 100));
    f.info_density = content.length / nw;
    f.clarity = Math.max(0, Math.min(1, 1 - Math.abs(w.length - 9) / 14));
    return f;
  }

  // --------------------------------------------------------------- scoring
  /** Per-platform model when it generalised on holdout, else the pooled one. */
  function pickModel(plat) {
    if (MODEL.recommended_model && MODEL.recommended_model[plat] === 'platform') {
      return [MODEL.platforms[plat].full, 'platform'];
    }
    return [MODEL.pooled.full, 'pooled'];
  }

  function scoreTitle(title, plat) {
    const f = titleFeatures(title);
    const [m, which] = pickModel(plat);
    let s = m.intercept;
    for (const k of m.features) {
      const v = k.startsWith('plat_') ? (('plat_' + plat) === k ? 1 : 0) : f[k];
      s += ((v - m.mean[k]) / m.std[k]) * m.weights[k];
    }
    return { f, raw: s, pct: Math.max(0, Math.min(100, s * 100)), model: which };
  }

  const band = p => (p >= 60 ? ['strong', 'above average'] :
    p >= 45 ? ['mixed', 'middle of the pack'] : ['weak', 'below average']);

  // ----------------------------------------------------------- diagnostics
  function diagnose(f, plat) {
    const R = RULES[plat];
    const lifts = {};
    [...R.do, ...R.avoid].forEach(d => { lifts[d.k] = d.v; });
    const wc = f.word_count;
    const out = [];

    const checks = [
      ['starts_with_number', f.starts_with_number === 1],
      ['has_colon', f.has_colon === 1],
      ['is_question', f.has_question === 1],
      ['big_number_specific', f.has_big_number === 1],
      ['authority_marker', f.authority_markers >= 1],
      ['negative_framing', f.negative_words >= 1],
      ['strong_negative_framing', f.negative_words >= 2],
      ['curiosity_marker', f.curiosity_markers >= 1],
      ['beginner_framing', f.beginner_markers >= 1],
      ['deep_technical', f.tech_depth_markers >= 1],
      ['money_figure', f.has_money === 1],
      ['addresses_you', f.second_person === 1],
      ['superlative', f.has_superlative === 1],
      ['mentions_year', f.has_year === 1],
      ['ai_tell_phrasing', f.ai_tells >= 1],
      ['short_title_<=7w', wc <= 7],
      ['medium_title_8_12w', wc >= 8 && wc <= 12],
      ['long_title_>=13w', wc >= 13]
    ];

    checks.forEach(([k, present]) => {
      if (!present || !(k in lifts)) return;
      const v = lifts[k];
      out.push({
        cls: v > 0 ? 'good' : (v < -4 ? 'bad' : 'warn'),
        html: `You ${COND[k] || k}. On ${PLAT_NAME[plat]} that is worth <b>${v > 0 ? '+' : ''}${v.toFixed(1)}</b> percentile points.`
      });
    });

    if (f.all_caps_words > 0) out.push({ cls: 'warn', html: `${f.all_caps_words} ALL-CAPS word(s). Negatively correlated on every platform.` });
    if (!f.has_big_number) out.push({ cls: 'warn', html: 'No specific number with a unit. This is the most portable positive signal in the corpus.' });
    if (f.authority_markers === 0) out.push({ cls: 'warn', html: 'No first-hand evidence marker ("we built", "I spent", "in production", "measured").' });
    return out;
  }

  // ------------------------------------------------------------ generation
  function topicTerms(topic) {
    const stop = new Set(LEX.STOP.concat(['using', 'with', 'from', 'into', 'about', 'this', 'that']));
    const seen = new Set();
    const out = [];
    (topic.match(/[A-Za-z][A-Za-z0-9+#.\-]{1,}/g) || []).forEach(w => {
      const l = w.toLowerCase();
      if (stop.has(l) || l.length < 3 || seen.has(l)) return;
      seen.add(l);
      out.push(w);
    });
    return out;
  }

  function fill(tpl, terms) {
    const T = terms[0] || 'the system';
    const X = terms[1] || terms[0] || 'it';
    const M = terms.find(t => /latency|cost|time|memory|error|throughput|churn|load|size|speed/i.test(t)) || 'p99 latency';
    const N = [3, 5, 7, 10, 12, 40, 60, 90][Math.floor(Math.random() * 8)];
    const N2 = Math.max(1, Math.round(N / 3));
    return tpl.replace(/\{T\}/g, T).replace(/\{X\}/g, X).replace(/\{M\}/g, M)
      .replace(/\{N2\}/g, N2).replace(/\{N\}/g, N);
  }

  function generate(topic, plat) {
    const terms = topicTerms(topic);
    const out = [];
    for (const [kind, list] of Object.entries(TEMPLATES)) {
      list.forEach(tpl => {
        const t = fill(tpl, terms);
        const s = scoreTitle(t, plat);
        out.push({ kind, title: t, pct: s.pct, f: s.f });
      });
    }
    return out.sort((a, b) => b.pct - a.pct);
  }

  function suggestTags(topic) {
    const terms = topicTerms(topic).map(t => t.toLowerCase());
    const scored = Object.entries(TAGS).map(([tag, v]) => {
      let rel = 0;
      terms.forEach(x => { if (tag.includes(x) || x.includes(tag)) rel += 1; });
      return { tag, n: v.n, mean: v.mean, rel };
    });
    return {
      relevant: scored.filter(s => s.rel > 0).sort((a, b) => b.mean - a.mean).slice(0, 8),
      strong: scored.filter(s => s.rel === 0).sort((a, b) => b.mean - a.mean).slice(0, 10)
    };
  }

  function buildPrompt(topic, plat, title, sub) {
    const R = RULES[plat];
    const doL = R.do.map(d => `  - ${COND[d.k] || d.k} (${d.v > 0 ? '+' : ''}${d.v.toFixed(1)} pts)`).join('\n');
    const avL = R.avoid.map(d => `  - ${COND[d.k] || d.k} (${d.v.toFixed(1)} pts)`).join('\n');
    return `You are writing a headline for ${PLAT_NAME[plat]}.

TOPIC / CONTENT
${topic}${title ? `\n\nCURRENT DRAFT TITLE\n${title}` : ''}${sub ? `\n\nCURRENT SUBTITLE\n${sub}` : ''}

MEASURED RULES FOR THIS PLATFORM (from ${R.n.toLocaleString()} top posts)
Median headline: ${R.median_words} words / ${R.median_chars} characters.
Rewards:
${doL}
Penalises:
${avL}

PORTABLE RULES (held on every platform tested)
  - Include one concrete number WITH A UNIT (40%, 500ms, 3 years, $12k). Not a listicle count.
  - Show first-hand evidence: "we measured", "I built", "in production", "postmortem".
  - Cut ornamentation: no ALL-CAPS, no stacked acronyms, at most one adjective.
  - The subtitle must not restate the title. Target 10-18 words, overlap under 25%,
    and make it easier to read than the title.

TASK
Write 8 title candidates across these claim types: result, build log, postmortem,
teaching, position, comparison. For the best 3, write a matching subtitle.
Then recommend 3-4 tags: one broad, one mid, one specific.
No preamble. Output as a numbered list.`;
  }

  // ------------------------------------------------------------------- UI
  const $ = id => document.getElementById(id);
  const esc = s => String(s).replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
  let currentKind = 'all';
  let candidates = [];

  function renderRules(plat) {
    const R = RULES[plat];
    const tbl = rows => `<div class="tablewrap"><table>`
      + `<thead><tr><th>Move</th><th class="num">Lift</th><th class="num">n</th></tr></thead><tbody>`
      + rows.map(d => `<tr><td>${esc(COND[d.k] || d.k)}</td>`
        + `<td class="num ${d.v > 0 ? 'pos' : 'neg'}">${d.v > 0 ? '+' : ''}${d.v.toFixed(1)}</td>`
        + `<td class="num">${d.n}</td></tr>`).join('') + '</tbody></table></div>';
    $('rules').innerHTML =
      `<p class="note">Measured on ${R.n.toLocaleString()} ${PLAT_NAME[plat]} posts. Lift is the difference in mean
       engagement percentile between posts with and without the property.</p>
       <h3 style="margin-top:1rem">Rewards</h3>${tbl(R.do)}
       <h3 style="margin-top:1.25rem">Penalises</h3>${tbl(R.avoid)}`;
  }

  function renderCandidates() {
    const list = candidates.filter(c => currentKind === 'all' || c.kind === currentKind).slice(0, 12);
    $('cands').innerHTML = list.map(c => `
      <div class="item">
        <div class="item-title">${esc(c.title)}</div>
        <div class="item-meta">
          <span class="chip">${esc(c.kind)}</span>
          <span class="mono"><b>${c.pct.toFixed(0)}</b>/100</span>
          <span>${c.f.word_count} words</span>
          ${c.f.has_big_number ? '<span class="chip good">specific number</span>' : ''}
          ${c.f.authority_markers ? '<span class="chip good">authority</span>' : ''}
          ${c.f.ai_tells ? '<span class="chip bad">AI cliché</span>' : ''}
        </div>
      </div>`).join('') || '<p class="note">No candidates yet.</p>';
    document.querySelectorAll('#ctabs button').forEach(b =>
      b.setAttribute('aria-pressed', String(b.dataset.kind === currentKind)));
  }

  function run() {
    const plat = $('plat').value;
    const title = $('title').value.trim();
    const sub = $('sub').value.trim();
    const topic = $('topic').value.trim() || title;

    if (title) {
      const s = scoreTitle(title, plat);
      const [cls, label] = band(s.pct);
      $('score').innerHTML =
        `<div class="score-head"><span class="score-value">${s.pct.toFixed(0)}</span>
         <span class="score-band band-${cls}">${label}</span></div>
         <div class="bar"><i style="width:${s.pct}%"></i></div>`;
      const [m, which] = pickModel(plat);
      $('scorenote').innerHTML =
        `Predicted engagement percentile for ${PLAT_NAME[plat]}, using the <b>${which}</b> model
         (holdout R² ${m.r2_holdout.toFixed(3)}, rank correlation ρ ${m.spearman_holdout.toFixed(2)}
         on ${m.n_holdout} unseen posts). Use it to rank your own drafts — not to predict reach.`;

      const w = MODEL.axis_weights_by_platform[plat] || MODEL.pooled.axes.weights;
      $('axes').innerHTML = MODEL.axes.map(a => {
        const val = s.f[a], weight = w[a] || 0;
        return `<div class="axis">
          <div class="axis-top"><strong>${esc(MODEL.axis_labels[a])}</strong>
          <span class="mono">${val.toFixed(2)} × ${weight >= 0 ? '+' : ''}${weight.toFixed(3)}</span></div>
          <div class="bar"><i class="${weight >= 0 ? 'pos' : 'neg'}" style="width:${Math.max(0, Math.min(100, val * 100))}%"></i></div>
        </div>`;
      }).join('');

      $('flags').innerHTML = diagnose(s.f, plat)
        .map(x => `<div class="flag ${x.cls}">${x.html}</div>`).join('');
    }

    if (topic) {
      candidates = generate(topic, plat);
      const kinds = ['all', ...new Set(candidates.map(c => c.kind))];
      $('ctabs').innerHTML = kinds.map(k =>
        `<button class="ghost" data-kind="${k}" aria-pressed="${k === currentKind}">${k}</button>`).join('');
      $('ctabs').querySelectorAll('button').forEach(b =>
        b.addEventListener('click', () => { currentKind = b.dataset.kind; renderCandidates(); }));
      renderCandidates();

      const terms = topicTerms(topic);
      $('subs').innerHTML = SUBSHAPES.map(([name, tpl]) => {
        const s = fill(tpl, terms);
        const wc = (s.match(/[A-Za-z0-9'\-]+/g) || []).length;
        const ok = wc >= 10 && wc <= 18;
        return `<div class="item"><div class="item-title">${esc(s)}</div>
          <div class="item-meta"><span class="chip">${esc(name)}</span><span>${wc} words</span>
          <span class="${ok ? 'pos' : 'neg'}">${ok ? 'in the 10–18 word band' : 'outside the 10–18 word band'}</span>
          </div></div>`;
      }).join('');

      const tg = suggestTags(topic);
      const chip = t => `<span class="chip${t.mean > 0.55 ? ' good' : ''}">${esc(t.tag)} <b class="mono">${(t.mean * 100).toFixed(0)}</b></span>`;
      $('tags').innerHTML =
        (tg.relevant.length ? `<p class="note">Matched to your topic</p><p>${tg.relevant.map(chip).join('')}</p>` : '')
        + `<p class="note" style="margin-top:.75rem">Highest-performing tags in the corpus</p><p>${tg.strong.map(chip).join('')}</p>`;

      $('prompt').textContent = buildPrompt(topic, plat, title, sub);
    }
    renderRules(plat);
  }

  function demo() {
    $('title').value = 'How we cut p99 latency 40% by deleting one Postgres index';
    $('sub').value = 'Three weeks, two rollbacks, and a lot of EXPLAIN ANALYZE.';
    $('topic').value = 'Postgres query performance indexing production database latency';
    run();
  }

  // ------------------------------------------------------------------ init
  document.addEventListener('DOMContentLoaded', () => {
    const sel = $('plat');
    sel.innerHTML = Object.keys(RULES).map(p =>
      `<option value="${p}">${PLAT_NAME[p] || p} — ${RULES[p].n.toLocaleString()} posts</option>`).join('');
    sel.value = 'hackernews';
    sel.addEventListener('change', run);

    $('go').addEventListener('click', run);
    $('demo').addEventListener('click', demo);
    $('copy').addEventListener('click', async () => {
      await navigator.clipboard.writeText($('prompt').textContent);
      $('copy').textContent = 'Copied';
      setTimeout(() => { $('copy').textContent = 'Copy prompt'; }, 1500);
    });
    $('title').addEventListener('keydown', e => { if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) run(); });

    document.querySelectorAll('[data-meta]').forEach(el => {
      el.textContent = META[el.dataset.meta];
    });
    renderRules('hackernews');
  });
})();
